def make_hashable(obj):
    if isinstance(obj, (tuple, list)):
        return tuple((make_hashable(elem) for elem in obj))
    elif isinstance(obj, dict):
        return tuple(sorted((key, make_hashable(val)) for key, val in obj.items()))
    else:
        return obj


def recreate_structure(hashable):
    if isinstance(hashable, tuple) and all(isinstance(item, tuple) and len(item) == 2 for item in hashable):
        return {key: recreate_structure(val) for key, val in hashable}
    elif isinstance(hashable, tuple):
        return tuple(recreate_structure(item) for item in hashable)
    else:
        return hashable


from collections import deque

def BFS(transition_dict, target_state, initial="INITIAL"):
    """
    transition_dict: { (state, input) : next_state }
    target_state: state we want to reach

    Returns: list of inputs (commands), or None if unreachable
    """
    queue = deque()
    queue.append((initial, []))   # (current_state, input_sequence)
    visited = set([initial])

    while queue:
        state, seq = queue.popleft()

        if state == target_state:
            return seq

        for (s, inp), next_state in transition_dict.items():
            if s == state and next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, seq + [inp]))

    return None



